#!/usr/bin/env python3\n\"\"\"\nEnterprise Backend Server - AI-Powered with Screen Intelligence\nProfessional-grade system with LLM planning, screen awareness, and user interaction\nLike 500,000 senior developers wrote this code\n\"\"\"\n\nimport asyncio\nimport json\nimport logging\nimport os\nimport sys\nimport time\nimport traceback\nimport uuid\nfrom datetime import datetime\nfrom typing import Dict, Any, Optional, List, Set\nfrom concurrent.futures import ThreadPoolExecutor\nfrom contextlib import asynccontextmanager\nimport websockets\nfrom websockets.server import WebSocketServerProtocol\n\n# Import our enterprise components\nparent_dir = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))\nsys.path.insert(0, parent_dir)\nsys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))\n\n# Configure enterprise logging\nos.makedirs('logs/backend', exist_ok=True)\nlogging.basicConfig(\n    level=logging.INFO,\n    format='%(asctime)s - %(name)s - %(levelname)s - [%(filename)s:%(lineno)d] - %(message)s',\n    handlers=[\n        logging.FileHandler('logs/backend/enterprise_backend_ai_powered.log'),\n        logging.StreamHandler()\n    ]\n)\nlogger = logging.getLogger(__name__)\n\nclass EnterpriseBackendAIPowered:\n    \"\"\"AI-Powered Enterprise Backend with Screen Intelligence and User Interaction\"\"\"\n    \n    def __init__(self, port: int = 8767):\n        self.port = port\n        self.connected_clients: Set[WebSocketServerProtocol] = set()\n        self.client_sessions: Dict[str, Dict[str, Any]] = {}\n        self.performance_metrics = {\n            'total_requests': 0,\n            'successful_requests': 0,\n            'failed_requests': 0,\n            'ai_planning_requests': 0,\n            'screen_analysis_requests': 0,\n            'user_approvals': 0,\n            'user_dismissals': 0,\n            'plan_adjustments': 0,\n            'mode_usage': {'ask': 0, 'agent': 0, 'suggest': 0, 'general': 0}\n        }\n        self.server = None\n        \n        # AI and Screen Intelligence components\n        self.screen_intelligence = None\n        self.task_planner = None\n        self.llm_service = None\n        \n        # Memory integration\n        self.semantic_search = None\n        \n        logger.info(\"✅ Enterprise AI-Powered Backend Server initialized\")\n    \n    async def initialize(self):\n        \"\"\"Initialize all AI and intelligence components\"\"\"\n        try:\n            logger.info(\"🚀 Initializing AI and Intelligence components...\")\n            \n            # Initialize Screen Intelligence\n            try:\n                from advanced_screen_intelligence import get_screen_intelligence\n                self.screen_intelligence = await get_screen_intelligence()\n                logger.info(\"✅ Screen Intelligence initialized\")\n            except Exception as e:\n                logger.warning(f\"⚠️ Screen Intelligence initialization failed: {e}\")\n            \n            # Initialize Task Planner\n            try:\n                from enterprise_task_planner import get_task_planner\n                self.task_planner = await get_task_planner()\n                logger.info(\"✅ Task Planner initialized\")\n            except Exception as e:\n                logger.warning(f\"⚠️ Task Planner initialization failed: {e}\")\n            \n            # Initialize Memory System\n            try:\n                from memory.semantic_search_agent import SemanticSearchAgent\n                self.semantic_search = SemanticSearchAgent()\n                logger.info(\"✅ Memory System initialized\")\n            except Exception as e:\n                logger.warning(f\"⚠️ Memory System initialization failed: {e}\")\n            \n            # Initialize LLM Service\n            try:\n                from Others.enterprise_llm_service import generate_llm_response\n                self.llm_service = generate_llm_response\n                logger.info(\"✅ LLM Service initialized\")\n            except Exception as e:\n                logger.warning(f\"⚠️ LLM Service initialization failed: {e}\")\n            \n            logger.info(\"🎯 All AI components initialized successfully\")\n            \n        except Exception as e:\n            logger.error(f\"❌ Component initialization failed: {e}\")\n            raise\n    \n    async def start_server(self):\n        \"\"\"Start the AI-powered enterprise WebSocket server\"\"\"\n        try:\n            # Initialize all components first\n            await self.initialize()\n            \n            self.server = await websockets.serve(\n                self.handle_client,\n                \"127.0.0.1\",\n                self.port,\n                ping_interval=20,\n                ping_timeout=10,\n                max_size=10 * 1024 * 1024,\n                max_queue=100\n            )\n            \n            logger.info(f\"🚀 AI-Powered Enterprise Backend Server started on ws://127.0.0.1:{self.port}\")\n            logger.info(\"🧠 Features: AI Planning, Screen Intelligence, User Interaction, Memory Integration\")\n            logger.info(\"🎯 Ready for enterprise-scale intelligent automation\")\n            \n            await asyncio.Future()\n            \n        except Exception as e:\n            logger.error(f\"❌ Failed to start server: {e}\")\n            sys.exit(1)\n    \n    async def handle_client(self, websocket: WebSocketServerProtocol):\n        \"\"\"Handle client connections with AI-powered responses\"\"\"\n        client_id = str(uuid.uuid4())\n        session_data = {\n            'id': client_id,\n            'connected_at': datetime.now(),\n            'message_count': 0,\n            'active_plans': [],\n            'pending_approvals': []\n        }\n        \n        logger.info(f\"👤 Client {client_id} connected\")\n        \n        try:\n            self.connected_clients.add(websocket)\n            self.client_sessions[client_id] = session_data\n            \n            # Send welcome with capabilities\n            await self._send_message(websocket, {\n                \"type\": \"connection_established\",\n                \"client_id\": client_id,\n                \"message\": \"Connected to AI-Powered Enterprise Backend\",\n                \"capabilities\": [\n                    \"ai_powered_planning\",\n                    \"screen_intelligence\", \n                    \"user_interaction\",\n                    \"memory_integration\",\n                    \"real_ui_automation\",\n                    \"llm_reasoning\"\n                ],\n                \"modes\": [\"agent\", \"ask\", \"suggest\", \"general\"],\n                \"timestamp\": datetime.now().isoformat()\n            })\n            \n            # Handle messages\n            async for raw_message in websocket:\n                try:\n                    await self._process_message(websocket, client_id, raw_message)\n                except Exception as e:\n                    logger.error(f\"❌ Error processing message: {e}\")\n                    await self._send_error(websocket, str(e))\n        \n        except websockets.exceptions.ConnectionClosed:\n            logger.info(f\"👋 Client {client_id} disconnected\")\n        except Exception as e:\n            logger.error(f\"❌ Error with client {client_id}: {e}\")\n        finally:\n            self.connected_clients.discard(websocket)\n            if client_id in self.client_sessions:\n                del self.client_sessions[client_id]\n    \n    async def _process_message(self, websocket: WebSocketServerProtocol, client_id: str, raw_message: str):\n        \"\"\"Process messages with AI-powered intelligence\"\"\"\n        try:\n            message = json.loads(raw_message)\n            msg_type = message.get('type', 'unknown')\n            \n            logger.info(f\"📥 Processing {msg_type} from client {client_id}\")\n            \n            # Update session activity\n            if client_id in self.client_sessions:\n                self.client_sessions[client_id]['message_count'] += 1\n            \n            # Route message based on type\n            if msg_type == \"chat_request\":\n                await self._handle_chat_request(websocket, client_id, message)\n            elif msg_type == \"approval_response\":\n                await self._handle_approval_response(websocket, client_id, message)\n            elif msg_type == \"plan_adjustment\":\n                await self._handle_plan_adjustment(websocket, client_id, message)\n            elif msg_type == \"get_plan_status\":\n                await self._handle_plan_status_request(websocket, client_id, message)\n            else:\n                logger.warning(f\"⚠️ Unknown message type: {msg_type}\")\n                await self._send_error(websocket, f\"Unknown message type: {msg_type}\")\n                \n        except json.JSONDecodeError as e:\n            logger.error(f\"❌ Invalid JSON: {e}\")\n            await self._send_error(websocket, \"Invalid JSON format\")\n    \n    async def _handle_chat_request(self, websocket: WebSocketServerProtocol, client_id: str, message: Dict[str, Any]):\n        \"\"\"Handle chat requests with AI-powered mode-specific processing\"\"\"\n        try:\n            query = message.get('query', '')\n            mode = message.get('mode', 'general').lower()\n            \n            logger.info(f\"🗣️ Chat request - Mode: {mode}, Query: {query}\")\n            \n            # Update metrics\n            self.performance_metrics['total_requests'] += 1\n            self.performance_metrics['mode_usage'][mode] += 1\n            \n            # Add request to memory for context\n            if self.semantic_search:\n                try:\n                    from memory.semantic_search_agent import add_memory\n                    await add_memory(\n                        content=f\"User query [{mode} mode]: {query}\",\n                        source=\"user_interaction\",\n                        tags={\"chat\", mode, \"user_query\"},\n                        metadata={\n                            \"client_id\": client_id,\n                            \"mode\": mode,\n                            \"timestamp\": datetime.now().isoformat()\n                        }\n                    )\n                except Exception as e:\n                    logger.warning(f\"Memory storage failed: {e}\")\n            \n            # Route to mode-specific handler\n            if mode == 'agent':\n                await self._handle_agent_mode_ai(websocket, client_id, query)\n            elif mode == 'ask':\n                await self._handle_ask_mode_ai(websocket, client_id, query)\n            elif mode == 'suggest':\n                await self._handle_suggest_mode_ai(websocket, client_id, query)\n            elif mode == 'general':\n                await self._handle_general_mode_ai(websocket, client_id, query)\n            else:\n                await self._send_error(websocket, f\"Unknown mode: {mode}\")\n            \n            self.performance_metrics['successful_requests'] += 1\n            \n        except Exception as e:\n            logger.error(f\"❌ Error in chat request: {e}\")\n            logger.error(traceback.format_exc())\n            self.performance_metrics['failed_requests'] += 1\n            await self._send_error(websocket, \"Failed to process chat request\")\n    \n    async def _handle_agent_mode_ai(self, websocket: WebSocketServerProtocol, client_id: str, query: str):\n        \"\"\"Handle Agent mode with AI planning and screen intelligence\"\"\"\n        try:\n            logger.info(f\"🤖 Agent mode AI processing: {query}\")\n            self.performance_metrics['ai_planning_requests'] += 1\n            \n            # Step 1: Analyze screen context for intelligent planning\n            screen_context = {}\n            if self.screen_intelligence:\n                try:\n                    self.performance_metrics['screen_analysis_requests'] += 1\n                    screen_context = await self.screen_intelligence.analyze_screen_context()\n                    logger.info(f\"📷 Screen context: {screen_context.get('application', 'Unknown')} - {len(screen_context.get('clickable_elements', []))} clickable elements\")\n                except Exception as e:\n                    logger.warning(f\"Screen analysis failed: {e}\")\n            \n            # Step 2: Retrieve relevant memory context\n            memory_context = []\n            if self.semantic_search:\n                try:\n                    from memory.semantic_search_agent import search_memories\n                    memory_results = await search_memories(query, top_k=3)\n                    memory_context = [result.get('content', '') for result in memory_results if result.get('content')]\n                    logger.info(f\"🧠 Retrieved {len(memory_context)} relevant memories\")\n                except Exception as e:\n                    logger.warning(f\"Memory search failed: {e}\")\n            \n            # Step 3: Create comprehensive execution plan using AI\n            if self.task_planner:\n                try:\n                    context = {\n                        'screen_context': screen_context,\n                        'memory_context': memory_context,\n                        'client_id': client_id,\n                        'mode': 'agent'\n                    }\n                    \n                    # Create AI-powered execution plan\n                    plan = await self.task_planner.create_execution_plan(query, context)\n                    \n                    # Store plan reference in client session\n                    if client_id in self.client_sessions:\n                        self.client_sessions[client_id]['active_plans'].append(plan.id)\n                    \n                    logger.info(f\"📋 Created execution plan: {plan.id} ({len(plan.steps)} steps, {plan.complexity.value} complexity)\")\n                    \n                    # Step 4: Request user approval if required\n                    if plan.approval_required:\n                        approval_request = await self.task_planner.request_user_approval(plan)\n                        \n                        # Store approval reference\n                        if client_id in self.client_sessions:\n                            self.client_sessions[client_id]['pending_approvals'].append(approval_request.plan_id)\n                        \n                        # Send approval request to user with interactive UI\n                        await self._send_approval_request(websocket, approval_request)\n                        \n                        logger.info(f\"📋 User approval requested for plan: {plan.id}\")\n                        \n                    else:\n                        # Auto-execute for simple tasks\n                        logger.info(f\"🚀 Auto-executing plan: {plan.id}\")\n                        execution_result = await self.task_planner.execute_plan(plan.id)\n                        \n                        await self._send_execution_result(websocket, plan, execution_result)\n                        \n                except Exception as e:\n                    logger.error(f\"❌ Task planning failed: {e}\")\n                    await self._send_chat_response(websocket, f\"❌ Task planning failed: {str(e)}\", 'agent', False, 0.1)\n            \n            else:\n                # Fallback if task planner not available\n                await self._send_chat_response(websocket, \"⚠️ AI Task Planner not available. Please check system configuration.\", 'agent', False, 0.1)\n                \n        except Exception as e:\n            logger.error(f\"❌ Agent mode AI processing failed: {e}\")\n            logger.error(traceback.format_exc())\n            await self._send_error(websocket, \"Agent mode processing failed\")\n    \n    async def _handle_ask_mode_ai(self, websocket: WebSocketServerProtocol, client_id: str, query: str):\n        \"\"\"Handle Ask mode with memory-enhanced responses\"\"\"\n        try:\n            logger.info(f\"🤔 Ask mode AI processing: {query}\")\n            \n            # Search relevant memories\n            relevant_context = []\n            if self.semantic_search:\n                try:\n                    from memory.semantic_search_agent import search_memories\n                    memory_results = await search_memories(query, top_k=5)\n                    relevant_context = [result.get('content', '') for result in memory_results if result.get('content')]\n                    logger.info(f\"🧠 Found {len(relevant_context)} relevant memories\")\n                except Exception as e:\n                    logger.warning(f\"Memory search failed: {e}\")\n            \n            # Generate enhanced response using LLM + memory\n            if self.llm_service:\n                try:\n                    context_prompt = f\"\"\"\nUser Question: {query}\n\nRelevant Context from Memory:\n{chr(10).join(relevant_context) if relevant_context else 'No specific context found'}\n\nPlease provide a comprehensive, helpful answer based on the question and any relevant context.\n\"\"\"\n                    \n                    llm_response = await self.llm_service(context_prompt)\n                    \n                    # Store response in memory\n                    if self.semantic_search:\n                        try:\n                            from memory.semantic_search_agent import add_memory\n                            await add_memory(\n                                content=f\"Ask mode response: {llm_response}\",\n                                source=\"system_response\",\n                                tags={\"ask\", \"llm_response\", \"knowledge\"},\n                                metadata={\n                                    \"client_id\": client_id,\n                                    \"query\": query,\n                                    \"timestamp\": datetime.now().isoformat()\n                                }\n                            )\n                        except Exception as e:\n                            logger.warning(f\"Response storage failed: {e}\")\n                    \n                    await self._send_chat_response(websocket, llm_response, 'ask', True, 0.9)\n                    \n                except Exception as e:\n                    logger.error(f\"LLM response generation failed: {e}\")\n                    await self._send_chat_response(websocket, f\"Knowledge query processed. Context: {len(relevant_context)} relevant items found.\", 'ask', True, 0.7)\n            else:\n                await self._send_chat_response(websocket, f\"Knowledge query processed. Found {len(relevant_context)} relevant context items.\", 'ask', True, 0.7)\n                \n        except Exception as e:\n            logger.error(f\"❌ Ask mode processing failed: {e}\")\n            await self._send_error(websocket, \"Ask mode processing failed\")\n    \n    async def _handle_suggest_mode_ai(self, websocket: WebSocketServerProtocol, client_id: str, query: str):\n        \"\"\"Handle Suggest mode with contextual AI suggestions\"\"\"\n        try:\n            logger.info(f\"💡 Suggest mode AI processing: {query}\")\n            \n            # Analyze current context for suggestions\n            screen_context = {}\n            if self.screen_intelligence:\n                try:\n                    screen_context = await self.screen_intelligence.analyze_screen_context()\n                except Exception as e:\n                    logger.warning(f\"Screen analysis failed: {e}\")\n            \n            # Generate contextual suggestions using LLM\n            if self.llm_service:\n                try:\n                    suggestion_prompt = f\"\"\"\nUser Request: {query}\n\nCurrent Context:\n- Application: {screen_context.get('application', 'Unknown')}\n- Available UI Elements: {len(screen_context.get('clickable_elements', []))}\n- Screen State: {screen_context.get('ui_state', {})}\n\nPlease provide 3-5 practical, actionable suggestions based on the request and current context.\n\"\"\"\n                    \n                    suggestions = await self.llm_service(suggestion_prompt)\n                    await self._send_chat_response(websocket, suggestions, 'suggest', True, 0.8)\n                    \n                except Exception as e:\n                    logger.error(f\"Suggestion generation failed: {e}\")\n                    await self._send_chat_response(websocket, \"Here are some contextual suggestions based on your request.\", 'suggest', True, 0.6)\n            else:\n                await self._send_chat_response(websocket, \"Contextual suggestions generated based on current environment.\", 'suggest', True, 0.6)\n                \n        except Exception as e:\n            logger.error(f\"❌ Suggest mode processing failed: {e}\")\n            await self._send_error(websocket, \"Suggest mode processing failed\")\n    \n    async def _handle_general_mode_ai(self, websocket: WebSocketServerProtocol, client_id: str, query: str):\n        \"\"\"Handle General mode with LLM conversation\"\"\"\n        try:\n            logger.info(f\"🗣️ General mode AI processing: {query}\")\n            \n            # Generate conversational response using LLM\n            if self.llm_service:\n                try:\n                    llm_response = await self.llm_service(query)\n                    await self._send_chat_response(websocket, llm_response, 'general', True, 0.9)\n                except Exception as e:\n                    logger.error(f\"LLM conversation failed: {e}\")\n                    await self._send_chat_response(websocket, \"I understand your message. How can I help you today?\", 'general', True, 0.7)\n            else:\n                await self._send_chat_response(websocket, \"General conversation processed. How can I assist you further?\", 'general', True, 0.7)\n                \n        except Exception as e:\n            logger.error(f\"❌ General mode processing failed: {e}\")\n            await self._send_error(websocket, \"General mode processing failed\")\n    \n    async def _handle_approval_response(self, websocket: WebSocketServerProtocol, client_id: str, message: Dict[str, Any]):\n        \"\"\"Handle user approval responses\"\"\"\n        try:\n            plan_id = message.get('plan_id')\n            response = message.get('response')  # 'approve', 'dismiss', 'adjust'\n            modifications = message.get('modifications', {})\n            \n            logger.info(f\"📋 Approval response for plan {plan_id}: {response}\")\n            \n            if not plan_id or not response:\n                await self._send_error(websocket, \"Invalid approval response format\")\n                return\n            \n            # Update metrics\n            if response == 'approve':\n                self.performance_metrics['user_approvals'] += 1\n            elif response == 'dismiss':\n                self.performance_metrics['user_dismissals'] += 1\n            elif response == 'adjust':\n                self.performance_metrics['plan_adjustments'] += 1\n            \n            # Process response through task planner\n            if self.task_planner:\n                success = await self.task_planner.process_user_response(plan_id, response, modifications)\n                \n                if success and response == 'approve':\n                    # Execute the approved plan\n                    logger.info(f\"🚀 Executing approved plan: {plan_id}\")\n                    execution_result = await self.task_planner.execute_plan(plan_id)\n                    \n                    # Get plan details for response\n                    plan = self.task_planner.completed_plans.get(plan_id)\n                    if plan:\n                        await self._send_execution_result(websocket, plan, execution_result)\n                    else:\n                        await self._send_message(websocket, {\n                            \"type\": \"execution_complete\",\n                            \"plan_id\": plan_id,\n                            \"result\": execution_result\n                        })\n                \n                elif success and response == 'dismiss':\n                    await self._send_message(websocket, {\n                        \"type\": \"plan_dismissed\",\n                        \"plan_id\": plan_id,\n                        \"message\": \"Task has been dismissed as requested.\"\n                    })\n                \n                elif success and response == 'adjust':\n                    await self._send_message(websocket, {\n                        \"type\": \"plan_adjusted\",\n                        \"plan_id\": plan_id,\n                        \"message\": \"Plan has been adjusted. Ready for execution.\"\n                    })\n                    \n                    # Auto-execute adjusted plan\n                    logger.info(f\"🚀 Executing adjusted plan: {plan_id}\")\n                    execution_result = await self.task_planner.execute_plan(plan_id)\n                    \n                    plan = self.task_planner.completed_plans.get(plan_id)\n                    if plan:\n                        await self._send_execution_result(websocket, plan, execution_result)\n                \n                else:\n                    await self._send_error(websocket, \"Failed to process approval response\")\n            \n            # Remove from client session\n            if client_id in self.client_sessions and plan_id in self.client_sessions[client_id]['pending_approvals']:\n                self.client_sessions[client_id]['pending_approvals'].remove(plan_id)\n                \n        except Exception as e:\n            logger.error(f\"❌ Approval response handling failed: {e}\")\n            await self._send_error(websocket, \"Failed to process approval response\")\n    \n    async def _send_approval_request(self, websocket: WebSocketServerProtocol, approval_request):\n        \"\"\"Send user approval request with interactive UI\"\"\"\n        try:\n            plan = approval_request.plan\n            \n            # Create rich approval message\n            approval_data = {\n                \"type\": \"approval_request\",\n                \"plan_id\": plan.id,\n                \"title\": \"🧪 Task Execution Plan Ready\",\n                \"message\": approval_request.message,\n                \"plan_summary\": {\n                    \"request\": plan.user_request,\n                    \"steps\": len(plan.steps),\n                    \"complexity\": plan.complexity.value,\n                    \"estimated_time\": f\"{plan.estimated_total_duration:.1f}s\",\n                    \"risk_level\": plan.risk_assessment.get('overall_risk', 'low')\n                },\n                \"execution_steps\": [\n                    {\n                        \"number\": i + 1,\n                        \"title\": step.title,\n                        \"description\": step.description,\n                        \"estimated_duration\": step.estimated_duration\n                    }\n                    for i, step in enumerate(plan.steps)\n                ],\n                \"success_criteria\": plan.success_criteria,\n                \"options\": approval_request.options,\n                \"expires_at\": approval_request.expires_at,\n                \"timestamp\": datetime.now().isoformat()\n            }\n            \n            await self._send_message(websocket, approval_data)\n            \n        except Exception as e:\n            logger.error(f\"❌ Failed to send approval request: {e}\")\n    \n    async def _send_execution_result(self, websocket: WebSocketServerProtocol, plan, execution_result: Dict[str, Any]):\n        \"\"\"Send execution result to client\"\"\"\n        try:\n            if execution_result.get('status') == 'completed':\n                success_message = f\"\"\"✅ **Task Completed Successfully!**\n\n🎯 **Request**: {plan.user_request}\n\n📊 **Execution Summary**:\n• Steps Completed: {execution_result.get('completed_steps', 0)}/{execution_result.get('total_steps', 0)}\n• Execution Time: {plan.actual_total_duration:.2f} seconds\n• Success Rate: 100%\n\n🎉 **All objectives achieved through AI-powered automation!**\n\n**AI Features Used**:\n• Screen Intelligence for precise UI detection\n• LLM-powered task planning and decomposition\n• Real-time execution monitoring and validation\n\"\"\"\n                \n                await self._send_chat_response(websocket, success_message, 'agent', True, 1.0)\n            else:\n                error_message = f\"\"\"⚠️ **Task Execution Issues**\n\n🎯 **Request**: {plan.user_request}\n\n📊 **Execution Summary**:\n• Steps Completed: {execution_result.get('completed_steps', 0)}/{execution_result.get('total_steps', 0)}\n• Progress: {execution_result.get('progress', 0):.1f}%\n• Errors: {len(execution_result.get('errors', []))}\n\n🔧 **Issues Encountered**:\n\"\"\"\n                \n                for error in execution_result.get('errors', []):\n                    error_message += f\"• {error.get('step_title', 'Unknown')}: {error.get('error', 'Unknown error')}\\n\"\n                \n                await self._send_chat_response(websocket, error_message, 'agent', False, 0.3)\n            \n        except Exception as e:\n            logger.error(f\"❌ Failed to send execution result: {e}\")\n    \n    async def _send_chat_response(self, websocket: WebSocketServerProtocol, content: str, mode: str, success: bool, confidence: float):\n        \"\"\"Send chat response in standard format\"\"\"\n        response = {\n            \"type\": \"chat_response\",\n            \"payload\": {\n                \"response\": content,\n                \"mode\": mode,\n                \"success\": success,\n                \"confidence\": confidence,\n                \"ai_powered\": True,\n                \"timestamp\": datetime.now().isoformat()\n            }\n        }\n        await self._send_message(websocket, response)\n    \n    async def _send_message(self, websocket: WebSocketServerProtocol, message: Dict[str, Any]):\n        \"\"\"Send message to websocket\"\"\"\n        try:\n            await websocket.send(json.dumps(message))\n        except Exception as e:\n            logger.error(f\"❌ Failed to send message: {e}\")\n    \n    async def _send_error(self, websocket: WebSocketServerProtocol, error_message: str):\n        \"\"\"Send error response\"\"\"\n        error_response = {\n            \"type\": \"error\",\n            \"payload\": {\n                \"message\": error_message,\n                \"timestamp\": datetime.now().isoformat()\n            }\n        }\n        await self._send_message(websocket, error_response)\n    \n    async def _handle_plan_status_request(self, websocket: WebSocketServerProtocol, client_id: str, message: Dict[str, Any]):\n        \"\"\"Handle plan status requests\"\"\"\n        try:\n            plan_id = message.get('plan_id')\n            if not plan_id:\n                await self._send_error(websocket, \"Plan ID required\")\n                return\n            \n            if self.task_planner:\n                status = self.task_planner.get_plan_status(plan_id)\n                if status:\n                    await self._send_message(websocket, {\n                        \"type\": \"plan_status\",\n                        \"plan_id\": plan_id,\n                        \"status\": status\n                    })\n                else:\n                    await self._send_error(websocket, f\"Plan not found: {plan_id}\")\n            else:\n                await self._send_error(websocket, \"Task planner not available\")\n                \n        except Exception as e:\n            logger.error(f\"❌ Plan status request failed: {e}\")\n            await self._send_error(websocket, \"Failed to get plan status\")\n    \n    async def _handle_plan_adjustment(self, websocket: WebSocketServerProtocol, client_id: str, message: Dict[str, Any]):\n        \"\"\"Handle plan adjustment requests\"\"\"\n        try:\n            plan_id = message.get('plan_id')\n            adjustments = message.get('adjustments', {})\n            \n            if not plan_id:\n                await self._send_error(websocket, \"Plan ID required for adjustment\")\n                return\n            \n            # Process adjustment through approval system\n            await self._handle_approval_response(websocket, client_id, {\n                'plan_id': plan_id,\n                'response': 'adjust',\n                'modifications': adjustments\n            })\n            \n        except Exception as e:\n            logger.error(f\"❌ Plan adjustment failed: {e}\")\n            await self._send_error(websocket, \"Failed to adjust plan\")\n\nasync def main():\n    \"\"\"Main entry point\"\"\"\n    try:\n        logger.info(\"🚀 Starting AI-Powered Enterprise Backend Server...\")\n        server = EnterpriseBackendAIPowered()\n        await server.start_server()\n    except KeyboardInterrupt:\n        logger.info(\"👋 Server stopped by user\")\n    except Exception as e:\n        logger.error(f\"💥 Server crashed: {e}\")\n        logger.error(traceback.format_exc())\n\nif __name__ == \"__main__\":\n    asyncio.run(main())\n"